// 2. 限流 KeyResolver：优先使用网关注入的可信用户 ID，其次按 IP
@Bean
public KeyResolver userKeyResolver() {
    return exchange -> {
        String userId = exchange.getRequest().getHeaders().getFirst("X-User-Id");
        if (userId != null && !userId.isBlank()) {
            return Mono.just("user:" + userId);
        }
        String ip = exchange.getRequest().getRemoteAddress()
                .getAddress().getHostAddress();
        return Mono.just("ip:" + ip);
    };
}

// 3. JWT 鉴权 GlobalFilter：先清理伪造 Header，再注入可信身份
@Component
public class AuthFilter implements GlobalFilter, Ordered {
    @Autowired
    private JwtUtil jwtUtil;

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        String path = exchange.getRequest().getPath().value();
        if (isWhitelist(path)) {
            return chain.filter(exchange);
        }

        String authHeader = exchange.getRequest().getHeaders()
                .getFirst("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
            return exchange.getResponse().setComplete();
        }

        try {
            Claims claims = jwtUtil.parseToken(authHeader.substring(7));
            ServerHttpRequest mutated = exchange.getRequest()
                .mutate()
                .headers(headers -> {
                    // 先删除外部可能伪造的内部 Header
                    headers.remove("X-User-Id");
                    headers.remove("X-User-Role");
                    headers.remove("X-Tenant-Id");
                })
                .header("X-User-Id", claims.getSubject())
                .header("X-User-Role", claims.get("role", String.class))
                .header("X-Tenant-Id", claims.get("tenantId", String.class))
                .build();
            return chain.filter(exchange.mutate().request(mutated).build());
        } catch (Exception e) {
            exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
            return exchange.getResponse().setComplete();
        }
    }

    @Override
    public int getOrder() { return -100; }
}

// 4. 灰度 GlobalFilter：白名单优先 + 稳定哈希比例
@Component
public class GrayReleaseFilter implements GlobalFilter, Ordered {
    @Autowired
    private GrayRuleConfig grayRuleConfig;

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        String userId = exchange.getRequest().getHeaders()
                .getFirst("X-User-Id");
        if (userId == null || userId.isBlank()) {
            return chain.filter(exchange);
        }

        boolean isGray = grayRuleConfig.getGrayUsers().contains(userId)
                || stableBucket(userId) < grayRuleConfig.getGrayPercent();

        if (!isGray) {
            return chain.filter(exchange);
        }

        ServerHttpRequest mutated = exchange.getRequest()
            .mutate()
            .header("X-Gray", "true")
            .header("X-Gray-Rule-Version", grayRuleConfig.getVersion())
            .build();
        return chain.filter(exchange.mutate().request(mutated).build());
    }

    // 稳定哈希：同一用户 ID 始终映射到同一桶位，避免会话抖动
    private int stableBucket(String stableKey) {
        return Math.floorMod(stableKey.hashCode(), 100);
    }

    @Override
    public int getOrder() { return -50; }
}
